"""
Aggregate QC metrics across samples from fastp JSON and samtools flagstat outputs.
Produces a summary CSV and a read-attrition + mapping-rate plot.
CLI Version (can be run manually rather than via Snakemake)
"""

import argparse
import glob
import gzip
import json
import os
import re

import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import numpy as np
import pandas as pd


GENOME_SIZE = 247_684_536


# --- CLI Args ---
def parse_args():
    p = argparse.ArgumentParser(description="Aggregate QC metrics across samples.")
    p.add_argument("--fastp_dir", default=None,
                   help="Directory containing fastp JSON reports and samtools flagstat files.")
    p.add_argument("--depth_sample", default=None,
                   help="Optional ANGSD depthSample file for mean-depth summaries.")
    p.add_argument("--raw_fastq_dir", default=None,
                   help="Optional directory containing raw FASTQ files for pre-filtering QC.")
    p.add_argument("--output_dir", default=".",
                   help="Directory for the output CSV and plot.")
    return p.parse_args()


# --- Utility helpers ---

def infer_population(sample_name):
    if "_LP_" in sample_name:
        return sample_name.split("_LP_")[0]
    return sample_name


def infer_fastq_pair_key(path):
    name = os.path.basename(path)
    name = name.replace(".fastq.gz", "")
    name = name.replace(".fq.gz", "")
    name = name.replace(".fastq", "")
    name = name.replace(".fq", "")
    if re.search(r"_R1(?:_|$)", name):
        name = re.sub(r"_R1(?:_|$)", "", name)
    elif re.search(r"_R2(?:_|$)", name):
        name = re.sub(r"_R2(?:_|$)", "", name)
    elif re.search(r"_1(?:_|$)", name):
        name = re.sub(r"_1(?:_|$)", "", name)
    elif re.search(r"_2(?:_|$)", name):
        name = re.sub(r"_2(?:_|$)", "", name)
    else:
        name = re.sub(r"_[12](?:_|$)", "", name)
    return name.strip("_")


# --- Parse fastp JSON ---

def parse_fastp(json_path):
    with open(json_path) as f:
        d = json.load(f)
    summary = d["summary"]
    bf = summary["before_filtering"]
    af = summary["after_filtering"]
    filtering = d["filtering_result"]
    return {
        "sequencing": summary.get("sequencing"),
        "raw_reads": bf["total_reads"],
        "raw_read1_length": bf["read1_mean_length"],
        "raw_read2_length": bf["read2_mean_length"],
        "raw_bases": bf["total_bases"],
        "raw_coverage": bf["total_bases"] / GENOME_SIZE,
        "filtered_reads": af["total_reads"],
        "filtered_read1_length": af["read1_mean_length"],
        "filtered_read2_length": af["read2_mean_length"],
        "filtered_bases": af["total_bases"],
        "filtered_coverage": af["total_bases"] / GENOME_SIZE,
        "passed_filter": filtering["passed_filter_reads"],
        "low_quality": filtering["low_quality_reads"],
        "too_short": filtering["too_short_reads"],
        "too_many_N": filtering["too_many_N_reads"],
    }


# --- Parse samtools flagstat ---

def parse_flagstat(flagstat_path):
    with open(flagstat_path) as f:
        text = f.read()

    def extract(pattern):
        m = re.search(pattern, text, re.MULTILINE)
        return int(m.group(1)) if m else None

    total = extract(r"^(\d+) \+ \d+ in total")
    mapped = extract(r"^(\d+) \+ \d+ mapped")
    return {
        "flagstat_total": total,
        "mapped_reads": mapped,
        "mapping_rate": round(100 * mapped / total, 2) if (total and mapped) else None,
    }


# --- Parse summed depthSample ---

def parse_depth_sample(depth_path):
    """
    Parses a (summed) ANGSD depthSample file.
    Each row = one sample; columns = site counts at depth 0, 1, 2, ..., maxDepth.
    Returns a list of dicts, one per sample (in BAM list order).
    """
    arr = np.loadtxt(depth_path)

    if arr.ndim == 1:
        arr = arr[None, :]

    records = []
    depths = np.arange(arr.shape[1])

    for row in arr:
        total_sites = row.sum()
        covered_sites = row[1:].sum()
        mean_depth = (depths[1:] * row[1:]).sum() / covered_sites if covered_sites > 0 else 0
        records.append({
            "angsd_total_sites": int(total_sites),
            "angsd_covered_sites": int(covered_sites),
            "angsd_mean_depth": round(mean_depth, 2),
        })
    return records


# --- Raw FASTQ QC helpers ---

def count_fastq_stats(path):
    total_reads = 0
    total_bases = 0
    lengths = []
    open_func = gzip.open if path.endswith(".gz") else open

    with open_func(path, "rt", encoding="utf-8", errors="replace") as fh:
        while True:
            line1 = fh.readline()
            if not line1:
                break
            line2 = fh.readline()
            line3 = fh.readline()
            line4 = fh.readline()
            if not line2:
                break
            total_reads += 1
            seq = line2.rstrip("\n").rstrip("\r")
            total_bases += len(seq)
            lengths.append(len(seq))

    return total_reads, total_bases, float(np.mean(lengths)) if lengths else 0.0


def load_raw_fastq_records(raw_fastq_dir):
    if raw_fastq_dir is None:
        return []

    files = sorted(
        glob.glob(os.path.join(raw_fastq_dir, "*.fastq.gz"))
        + glob.glob(os.path.join(raw_fastq_dir, "*.fq.gz"))
        + glob.glob(os.path.join(raw_fastq_dir, "*.fastq"))
        + glob.glob(os.path.join(raw_fastq_dir, "*.fq"))
    )
    if not files:
        raise FileNotFoundError(f"No FASTQ files found under: {raw_fastq_dir}")

    pairs = {}
    for path in files:
        key = infer_fastq_pair_key(path)
        side = "R1" if "_R1" in os.path.basename(path) or "_1" in os.path.basename(path) else "R2"
        pairs.setdefault(key, {})[side] = path

    records = []
    for sample, pair in sorted(pairs.items()):
        r1_path = pair.get("R1")
        r2_path = pair.get("R2")
        if r1_path is None or r2_path is None:
            print(f"Skipping sample {sample}: missing one mate pair in raw FASTQ directory.")
            continue

        r1_reads, r1_bases, r1_len = count_fastq_stats(r1_path)
        r2_reads, r2_bases, r2_len = count_fastq_stats(r2_path)

        row = {
            "sample": sample,
            "population": infer_population(sample),
            "raw_reads": r1_reads,
            "raw_read1_length": r1_len,
            "raw_read2_length": r2_len,
            "raw_bases": r1_bases + r2_bases,
            "raw_coverage": (r1_bases + r2_bases) / GENOME_SIZE,
        }
        records.append(row)

    return records


def load_fastp_records(fastp_dir):
    if fastp_dir is None:
        return []

    fastp_dir = os.path.abspath(fastp_dir)
    fastp_jsons = sorted(glob.glob(os.path.join(fastp_dir, "*fastp_report.json")))
    if not fastp_jsons:
        raise FileNotFoundError(f"No fastp report JSON files found in: {fastp_dir}")

    flagstat_map = {
        os.path.basename(path).replace("_flagstat.txt", ""): path
        for path in glob.glob(os.path.join(fastp_dir, "*flagstat.txt"))
    }

    records = []
    for json_path in fastp_jsons:
        sample = os.path.basename(json_path).replace("_fastp_report.json", "")
        row = {"sample": sample, "population": infer_population(sample)}
        row.update(parse_fastp(json_path))
        flagstat_path = flagstat_map.get(sample)
        if flagstat_path is not None:
            row.update(parse_flagstat(flagstat_path))
        records.append(row)
    return records


# --- Plotting ---

def make_plot(df, output_plot):
    figure_panels = []
    if "raw_coverage" in df.columns:
        figure_panels.append(("Raw coverage", df["raw_coverage"], "Coverage"))
    if "mapped_reads" in df.columns:
        figure_panels.append(("Mapped reads", df["mapped_reads"], "Reads"))
    if "mapping_rate" in df.columns:
        figure_panels.append(("Mapping rate", df["mapping_rate"], "% reads mapped"))
    if "angsd_mean_depth" in df.columns:
        figure_panels.append(("Mean depth", df["angsd_mean_depth"], "Mean depth (x)"))

    if not figure_panels:
        if "raw_reads" in df.columns:
            figure_panels.append(("Raw reads", df["raw_reads"], "Reads"))

    if not figure_panels:
        raise ValueError("No QC columns available to plot.")

    fig, axes = plt.subplots(len(figure_panels), 1, figsize=(max(12, len(df) * 0.12), 3.5 * len(figure_panels)))
    if len(figure_panels) == 1:
        axes = [axes]

    x = np.arange(len(df))
    bar_width = 0.8
    for ax, (title, values, ylabel) in zip(axes, figure_panels):
        ax.bar(x, values, width=bar_width, color="#4d4d4d", edgecolor="black", linewidth=0.5)
        ax.set_title(title)
        ax.set_ylabel(ylabel)
        ax.set_xticks(x)
        ax.set_xticklabels(df["sample"], rotation=90, fontsize=6)
        ax.spines["top"].set_visible(False)
        ax.spines["right"].set_visible(False)
        ax.spines["left"].set_linewidth(0.8)
        ax.spines["bottom"].set_linewidth(0.8)

    fig.suptitle(f"QC summary — {len(df)} samples", fontsize=14, y=1.02)
    plt.tight_layout()
    plt.savefig(output_plot, dpi=300, bbox_inches="tight")
    print(f"QC plot saved to {output_plot}")


# --- Aggregate ---

def main():
    args = parse_args()
    if args.fastp_dir is None and args.raw_fastq_dir is None:
        raise SystemExit("Either --fastp_dir or --raw_fastq_dir must be provided.")

    if args.fastp_dir is not None:
        records = load_fastp_records(args.fastp_dir)
        if args.depth_sample is not None:
            depth_records = parse_depth_sample(args.depth_sample)
            if len(depth_records) != len(records):
                raise ValueError(
                    f"Depth file contains {len(depth_records)} rows but {len(records)} samples were found in the fastp directory."
                )
            for row, depth_rec in zip(records, depth_records):
                row.update(depth_rec)
    else:
        records = load_raw_fastq_records(args.raw_fastq_dir)

    if not records:
        raise ValueError("No QC records were available to aggregate.")

    df = pd.DataFrame(records).sort_values("sample").reset_index(drop=True)

    if "filtered_reads" in df.columns and "raw_reads" in df.columns:
        df["fastp_retention_pct"] = 100 * df["filtered_reads"] / df["raw_reads"]
        df["reads_lost_fastp"] = df["raw_reads"] - df["filtered_reads"]
        if "mapped_reads" in df.columns:
            df["reads_lost_mapping"] = df["filtered_reads"] - df["mapped_reads"]

    os.makedirs(args.output_dir, exist_ok=True)
    output_csv = os.path.join(args.output_dir, "aggregate_qc.csv")
    output_plot = os.path.join(args.output_dir, "aggregate_qc.png")

    df.to_csv(output_csv, index=False)
    print(f"QC table saved to {output_csv}")
    make_plot(df, output_plot)


if __name__ == "__main__":
    main()